// Advanced RAG ingestion: paragraph/sentence-aware recursive chunking with
// overlap carried across boundaries and markdown-heading metadata per chunk.
const config = $('Set - Config').first().json;
const raw = String($input.first().json.notesText || '');

const targetChunkSize = config.chunkSizeChars || 800;
const overlapChars = config.chunkOverlapChars || 120;

function splitIntoParagraphs(text) {
  return text.split(/\n{2,}/).map(p => p.trim()).filter(Boolean);
}

function splitIntoSentences(text) {
  const matches = text.match(/[^.!?]+[.!?]+(\s+|$)|[^.!?]+$/g);
  return (matches || [text]).map(s => s.trim()).filter(Boolean);
}

function detectHeading(paragraph) {
  const m = paragraph.match(/^(#{1,3})\s+(.*)$/m);
  return m ? m[2].trim() : null;
}

const paragraphs = splitIntoParagraphs(raw);
const chunks = [];
let buffer = '';
let bufferHeading = null;
let carryOverlap = '';

function pushChunk(text, heading) {
  const trimmed = text.trim();
  if (!trimmed) return;
  chunks.push({
    chunkId: 'chunk_' + (chunks.length + 1).toString().padStart(3, '0'),
    index: chunks.length,
    heading: heading || null,
    text: trimmed,
    charCount: trimmed.length,
    tokenEstimate: Math.ceil(trimmed.length / 4)
  });
}

for (const para of paragraphs) {
  const heading = detectHeading(para);
  if (heading) bufferHeading = heading;

  const sentences = splitIntoSentences(para);
  for (const sentence of sentences) {
    const candidate = (buffer + ' ' + sentence).trim();
    if (candidate.length > targetChunkSize && buffer.length > 0) {
      pushChunk(carryOverlap + ' ' + buffer, bufferHeading);
      carryOverlap = buffer.slice(Math.max(0, buffer.length - overlapChars));
      buffer = sentence;
    } else {
      buffer = candidate;
    }
  }
}
if (buffer.trim()) pushChunk(carryOverlap + ' ' + buffer, bufferHeading);

if (chunks.length === 0) {
  chunks.push({
    chunkId: 'chunk_001',
    index: 0,
    heading: null,
    text: raw.trim() || '(no notes provided)',
    charCount: raw.length,
    tokenEstimate: Math.ceil(raw.length / 4)
  });
}

return [{
  json: {
    ...config,
    notesText: raw,
    chunks,
    totalChunks: chunks.length,
    totalTokenEstimate: chunks.reduce((sum, c) => sum + c.tokenEstimate, 0)
  }
}];

// Advanced retrieval: hand-rolled cosine similarity ranking followed by a
// Maximal Marginal Relevance pass so retrieved chunks are relevant AND diverse.
const embResponse = $input.first().json;
const ctx = $('JS - Chunk Notes & Prepare Embedding Requests').first().json;
const topicCtx = $('Wait - For Topic/Scope Selection').first().json;

const vectors = (embResponse.data || []).map(d => d.embedding).filter(Boolean);

if (vectors.length < 2) {
  return [{
    json: {
      ...ctx,
      topic: topicCtx.topic || ctx.defaultTopic,
      retrievedChunks: [],
      retrievedContext: '',
      retrievedCount: 0,
      retrievalError: 'insufficient_embeddings'
    }
  }];
}

const queryVector = vectors[0];
const chunkVectors = vectors.slice(1);

function dot(a, b) { let s = 0; for (let i = 0; i < a.length; i++) s += a[i] * b[i]; return s; }
function norm(a) { return Math.sqrt(dot(a, a)); }
function cosineSim(a, b) { const n = norm(a) * norm(b); return n === 0 ? 0 : dot(a, b) / n; }

const scored = ctx.chunks.map((chunk, i) => ({
  ...chunk,
  similarity: cosineSim(queryVector, chunkVectors[i] || [])
})).sort((a, b) => b.similarity - a.similarity);

const topK = ctx.retrievalTopK || 6;
const simThreshold = ctx.similarityThreshold ?? 0.15;
const lambda = 0.7; // relevance vs diversity trade-off for MMR

function wordOverlapScore(a, b) {
  const wa = new Set(a.text.toLowerCase().split(/\W+/).filter(Boolean));
  const wb = new Set(b.text.toLowerCase().split(/\W+/).filter(Boolean));
  if (wa.size === 0 || wb.size === 0) return 0;
  const intersection = [...wa].filter(w => wb.has(w)).length;
  const union = new Set([...wa, ...wb]).size;
  return union === 0 ? 0 : intersection / union;
}

const pool = scored.filter(c => c.similarity >= simThreshold);
const selected = [];

while (selected.length < topK && pool.length > 0) {
  let bestIdx = 0;
  let bestScore = -Infinity;
  for (let i = 0; i < pool.length; i++) {
    const relevance = pool[i].similarity;
    const maxRedundancy = selected.length
      ? Math.max(...selected.map(s => wordOverlapScore(s, pool[i])))
      : 0;
    const mmrScore = lambda * relevance - (1 - lambda) * maxRedundancy;
    if (mmrScore > bestScore) { bestScore = mmrScore; bestIdx = i; }
  }
  selected.push(pool.splice(bestIdx, 1)[0]);
}

const retrievedContext = selected
  .map((c, i) => '[Source ' + (i + 1) + (c.heading ? ' - ' + c.heading : '') + ']\n' + c.text)
  .join('\n\n');

return [{
  json: {
    ...ctx,
    topic: topicCtx.topic || ctx.defaultTopic,
    retrievedChunks: selected,
    retrievedContext,
    retrievedCount: selected.length
  }
}];

// Advanced post-processing: safe JSON parse, schema validation, Jaccard-similarity
// dedup, and SM-2 spaced-repetition state initialization for every surviving card.
const item = $input.first().json;
const raw = item.text || item.output || item.response || '[]';
const ctx = $('JS - Vector Similarity Search & Context Assembly').first().json;

let cards = [];
try {
  const cleaned = String(raw).replace(/```json|```/g, '').trim();
  const parsed = JSON.parse(cleaned);
  cards = Array.isArray(parsed) ? parsed : (parsed.flashcards || []);
} catch (e) {
  cards = [];
}

// Schema validation: require non-empty question and answer strings
const valid = cards.filter(c => c
  && typeof c.question === 'string' && c.question.trim()
  && typeof c.answer === 'string' && c.answer.trim());

// Dedupe near-duplicate questions using Jaccard similarity over word sets
function jaccard(a, b) {
  const wa = new Set(a.toLowerCase().split(/\W+/).filter(Boolean));
  const wb = new Set(b.toLowerCase().split(/\W+/).filter(Boolean));
  if (wa.size === 0 || wb.size === 0) return 0;
  const intersection = [...wa].filter(w => wb.has(w)).length;
  const union = new Set([...wa, ...wb]).size;
  return union === 0 ? 0 : intersection / union;
}

const DUPLICATE_THRESHOLD = 0.75;
const deduped = [];
for (const card of valid) {
  const isDuplicate = deduped.some(existing => jaccard(existing.question, card.question) > DUPLICATE_THRESHOLD);
  if (!isDuplicate) deduped.push(card);
}

// Initialize SM-2 spaced-repetition state for each surviving card
const today = new Date().toISOString().slice(0, 10);
const finalCards = deduped.map((c, i) => ({
  cardId: 'card_' + (i + 1).toString().padStart(3, '0'),
  question: c.question.trim(),
  answer: c.answer.trim(),
  tags: Array.isArray(c.tags) ? c.tags : [],
  difficulty: ['easy', 'medium', 'hard'].includes(c.difficulty) ? c.difficulty : 'medium',
  sourceHeading: c.sourceHeading || null,
  sm2: {
    easinessFactor: 2.5,
    intervalDays: 0,
    repetitions: 0,
    nextReviewDate: today
  }
}));

return [{
  json: {
    ...ctx,
    flashcards: finalCards,
    flashcardCount: finalCards.length,
    duplicatesRemoved: valid.length - deduped.length,
    invalidCardsDropped: cards.length - valid.length
  }
}];

